// EXPERIMENT helper for grass3d.js / water3d.js: which picture to read from.
//
// Many maps ship as variants of one layout (day/night, event versions) with the
// same name and size, e.g. s350 West Wire Forest and its blue night version s351
// (red lake). Colour rules like "green = grass" or "blue = water" only make sense
// on the normal palette, so for a variant we find WHERE things are in the base
// map and take the COLOURS from the variant on screen.
//
// map-variants.json maps variantId -> baseId (generated by comparing map names,
// sizes and palettes; maps with no variants are absent from it).
let variants = null;
let variantsLoad = null;
const baseImgs = new Map(); // baseId -> Image | "loading" | "failed"

function ensureVariants() {
    if (variantsLoad) return;
    variantsLoad = fetch("map-variants.json")
        .then((r) => (r.ok ? r.json() : {}))
        .catch(() => ({}))
        .then((j) => { variants = j; });
}

// The image whose pixels decide where grass/water go, or null while it loads.
export function classSource(stageId, mapImg) {
    ensureVariants();
    if (variants === null) return null;
    const base = variants[stageId];
    if (!base) return mapImg;
    const e = baseImgs.get(base);
    if (e === undefined) {
        const img = new Image();
        img.onload = () => baseImgs.set(base, img);
        img.onerror = () => baseImgs.set(base, "failed");
        baseImgs.set(base, "loading");
        img.src = `assets/maps/${base}.png`;
        return null;
    }
    if (e === "loading") return null;
    if (e === "failed" || e.naturalWidth !== mapImg.naturalWidth
        || e.naturalHeight !== mapImg.naturalHeight) return mapImg;
    return e;
}
